// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Keep the test wide: any non-trivial deposit and collect amount.
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, depositAmount);

        address actor = address(0xbeef);
        vm.deal(actor, depositAmount);

        vm.startPrank(actor);
        c.SetLogFile(address(log_));
        c.Deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(actor);
        uint256 ethBefore = actor.balance;
        c.Collect(collectAmount);
        uint256 balanceAfter = c.balances(actor);
        uint256 ethAfter = actor.balance;
        vm.stopPrank();

        // The general rule: the contract's recorded debt after Collect cannot be
        // greater than the debt before Collect minus what was actually paid out.
        // In the reference balanceAfter == balanceBefore - collectAmount (<= balanceBefore).
        // In the mutant balanceAfter == balanceBefore + collectAmount (> balanceBefore).
        assertTrue(balanceAfter <= balanceBefore);
    }
}
